namespace S=strata::deepseek41;namespace C=S::cuda;namespace K=strata::kernels;
constexpr int H=5120,V=129280,Half=V/2,T=8;constexpr size_t WeightBytes=542976000,HalfBytes=WeightBytes/2;
uint64_t f32_count=0,q_count=0,id_count=0;
void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
void need(bool x,const char*m){if(!x)throw std::runtime_error(m);}
struct B{int device;void*p{};size_t bytes;explicit B(size_t n):bytes(n){ck(cudaGetDevice(&device));ck(cudaMalloc(&p,n));}~B(){cudaSetDevice(device);cudaFree(p);}float*f(){return static_cast<float*>(p);}int32_t*i(){return static_cast<int32_t*>(p);}};
template<class A>struct Host{A*p{};size_t n;explicit Host(size_t count):n(count){ck(cudaMallocHost(&p,n*sizeof(A)));}~Host(){cudaFreeHost(p);}};
template<class A>void upload(B&b,const std::vector<A>&a,cudaStream_t s){need(a.size()*sizeof(A)<=b.bytes,"upload bounds");ck(cudaMemcpyAsync(b.p,a.data(),a.size()*sizeof(A),cudaMemcpyHostToDevice,s));ck(cudaStreamSynchronize(s));}
template<class A>std::vector<A>read(B&b,size_t n,cudaStream_t s,size_t offset=0){need((offset+n)*sizeof(A)<=b.bytes,"read bounds");std::vector<A>a(n);ck(cudaMemcpyAsync(a.data(),static_cast<uint8_t*>(b.p)+offset*sizeof(A),n*sizeof(A),cudaMemcpyDeviceToHost,s));ck(cudaStreamSynchronize(s));return a;}
template<class A>void eq(const std::vector<A>&a,const std::vector<A>&b,const char*m){need(a.size()==b.size(),"compare sizes");need(!std::memcmp(a.data(),b.data(),a.size()*sizeof(A)),m);}
std::vector<uint8_t>make_weights(){std::vector<uint8_t>w(WeightBytes);uint32_t state=910111;for(auto&b:w){state=state*1664525u+1013904223u;b=uint8_t(state>>24);}for(size_t i=0;i<w.size();i+=210){__half d=__float2half_rn(.0001f*(1+(i/210)%7));std::memcpy(w.data()+i+208,&d,2);}return w;}
struct Stage{int gpu;cudaStream_t stream{};B weight{WeightBytes},residual{H*4*T*4},pre{4*T*4},gamma{H*4},x{H*T*4},normal{H*T*4},q{K::native_q8_1_bytes(H,T)},il{K::native_q8_1_il_bytes(H,T)},full{size_t(V)*T*4+64},half{size_t(Half)*T*4+64},picks{T*4},pair{T*sizeof(S::HeadPick)};Host<int32_t>hostids{T};Host<S::HeadPick>hostpair{T};
 Stage(int device,const std::vector<uint8_t>&w):gpu(device){ck(cudaStreamCreateWithFlags(&stream,cudaStreamNonBlocking));upload(weight,w,stream);need(weight.bytes>201326592&&HalfBytes>201326592,"full and both halves must exceed2L2");K::SamplerParams p;p.greedy=true;p.temperature=0;ck(cudaMemsetAsync(full.p,0,V*4,stream));K::sample_tokens(full.f(),1,V,nullptr,0,p,picks.i(),stream);K::sample_tokens(full.f(),1,Half,nullptr,0,p,picks.i(),stream);ck(cudaStreamSynchronize(stream));}
 ~Stage(){cudaSetDevice(gpu);cudaStreamSynchronize(stream);cudaStreamDestroy(stream);}
 void input(int nt,int phase,const std::vector<float>*actual_gamma=nullptr){ck(cudaSetDevice(gpu));std::vector<float>r(size_t(H)*4*nt),p(4*nt),g(H);for(size_t i=0;i<r.size();++i)r[i]=phase?std::sin(float(i)*.013f+.3f*phase)*.2f:0.f;for(int t=0;t<nt;++t){for(int h=0;h<4;++h)p[t*4+h]=h?.17f*h:1.f;r[size_t(t)*H*4+33]=-0.f;r[size_t(t)*H*4+34]=std::ldexp(1.f,-140);if(phase==2)r[size_t(t)*H*4+57]=1e5f;}for(int i=0;i<H;++i)g[i]=1.f+.2f*std::sin(i*.017f);upload(residual,r,stream);upload(pre,p,stream);upload(gamma,actual_gamma?*actual_gamma:g,stream);}
 void project(int nt,int part){const int rows=part<0?V:Half;const uint8_t*w=static_cast<uint8_t*>(weight.p)+(part==1?HalfBytes:0);float*y=part<0?full.f():half.f();C::hc_pre(residual.f(),pre.f(),x.f(),H,nt,stream);C::rms(x.f(),gamma.f(),normal.f(),H,nt,1e-20f,stream);
 if(nt>=5){K::native_quantize_q8_1_il_wide(normal.f(),q.p,il.p,H,nt,stream);K::native_mmvq_il_wide(14,w,il.p,y,H,rows,nt,stream);}else if(nt>1&&K::native_mmvq_il_supported(14,nt,rows)){K::native_quantize_q8_1_il(normal.f(),q.p,il.p,H,nt,stream);K::native_mmvq_il(14,w,q.p,il.p,y,H,rows,nt,stream);}else{K::native_quantize_q8_1(normal.f(),q.p,H,nt,stream);K::native_mmvq(14,w,q.p,y,H,rows,nt,stream);}}
 void select(int nt,int part,bool pairs){const int rows=part<0?V:Half;float*y=part<0?full.f():half.f();K::SamplerParams p;p.greedy=true;p.temperature=0;K::sample_tokens(y,nt,rows,nullptr,0,p,picks.i(),stream);if(pairs){S::gather_head_picks(y,picks.i(),static_cast<S::HeadPick*>(pair.p),nt,rows,part==1?Half:0,stream);ck(cudaMemcpyAsync(hostpair.p,pair.p,nt*sizeof(S::HeadPick),cudaMemcpyDeviceToHost,stream));}else ck(cudaMemcpyAsync(hostids.p,picks.p,nt*4,cudaMemcpyDeviceToHost,stream));}
 void guard(B&b){ck(cudaMemsetAsync(b.p,0xcd,b.bytes,stream));}
 void check_guard(B&b,int count){auto tail=read<uint32_t>(b,16,stream,count);need(std::all_of(tail.begin(),tail.end(),[](uint32_t x){return x==0xcdcdcdcdu;}),"head output guard overwritten");}
};
struct G{cudaGraph_t g{};cudaGraphExec_t e{};template<class F>G(cudaStream_t s,F f){ck(cudaStreamBeginCapture(s,cudaStreamCaptureModeThreadLocal));f();ck(cudaStreamEndCapture(s,&g));ck(cudaGraphInstantiate(&e,g,nullptr,nullptr,0));}~G(){cudaGraphExecDestroy(e);cudaGraphDestroy(g);}void run(cudaStream_t s){ck(cudaGraphLaunch(e,s));ck(cudaStreamSynchronize(s));}
 void proof(const void*w,int rows){size_t n=0;ck(cudaGraphGetNodes(g,nullptr,&n));std::vector<cudaGraphNode_t>nodes(n);ck(cudaGraphGetNodes(g,nodes.data(),&n));int kernels=0;bool matrix=false,gather=false;for(auto node:nodes){cudaGraphNodeType type;ck(cudaGraphNodeGetType(node,&type));if(type!=cudaGraphNodeTypeKernel)continue;++kernels;cudaKernelNodeParams p{};ck(cudaGraphKernelNodeGetParams(node,&p));const char*name=nullptr;ck(cudaFuncGetName(&name,p.func));std::string k=name?name:"";void*first=nullptr;std::memcpy(&first,p.kernelParams[0],sizeof(first));if(k.find("mmvq")!=std::string::npos&&first==w)matrix=true;if(k.find("gather_picks_kernel")!=std::string::npos){int columns=0;std::memcpy(&columns,p.kernelParams[4],4);need(columns==rows,"wrong local logit stride in capture");gather=true;}}need(matrix&&gather&&kernels==6,"capture must prove full6kernel head and actual weight offset");}
};
void sampler_controls(Stage&a,Stage&b){constexpr int nt=8;std::vector<float>logits(size_t(V)*nt,-std::numeric_limits<float>::infinity());auto set=[&](int t,int id,float f){logits[size_t(t)*V+id]=f;};
 set(0,Half-1,10);set(0,Half,10);set(1,5,-0.f);set(1,Half+9,0.f);set(2,Half+3,std::numeric_limits<float>::infinity());set(2,2,std::numeric_limits<float>::quiet_NaN());for(int i=0;i<V;++i)set(3,i,std::numeric_limits<float>::quiet_NaN());set(4,V-1,11);set(4,0,-11);set(5,1,std::numeric_limits<float>::infinity());set(5,Half+1,std::numeric_limits<float>::infinity());set(7,Half,2);set(7,Half-1,std::nextafter(2.f,-std::numeric_limits<float>::infinity()));std::vector<int32_t>expected={Half-1,5,Half+3,0,V-1,1,0,Half};
 std::vector<int32_t>ref;for(Stage*z:{&a,&b}){ck(cudaSetDevice(z->gpu));upload(z->full,logits,z->stream);z->select(nt,-1,false);ck(cudaStreamSynchronize(z->stream));std::vector<int32_t>ids(z->hostids.p,z->hostids.p+nt);eq(ids,expected,"independent original sampler control differs");if(ref.empty())ref=ids;else eq(ref,ids,"crossGPU original sampler control differs");}
 for(int rank=0;rank<2;++rank){Stage&z=rank?b:a;ck(cudaSetDevice(z.gpu));std::vector<float>part(size_t(Half)*nt);for(int t=0;t<nt;++t)std::copy_n(logits.data()+size_t(t)*V+rank*Half,Half,part.data()+size_t(t)*Half);upload(z.half,part,z.stream);z.select(nt,rank,true);ck(cudaStreamSynchronize(z.stream));}
 int32_t merged[T];S::merge_head_picks(a.hostpair.p,b.hostpair.p,nt,V,merged);eq(expected,std::vector<int32_t>(merged,merged+nt),"boundary/ties/NaN/zero/inf/lastrow merge differs");id_count+=3*nt;std::cout<<"SAMPLER independent controls bothGPU full/split/merge boundary ties signedzero infinities NaN allNaN all-inf lastrow PASS\n";
}
int main(int argc,char**argv){try{K::native_mmvq_set_multi_exact(true);bool actual=argc==3&&std::string(argv[1])=="--actual";std::vector<uint8_t>w;std::vector<float>gamma;if(actual){std::ifstream f(argv[2],std::ios::binary);need(bool(f),"actual fixture missing");w.resize(WeightBytes);gamma.resize(H);f.read(reinterpret_cast<char*>(w.data()),w.size());f.read(reinterpret_cast<char*>(gamma.data()),gamma.size()*4);need(bool(f)&&f.peek()==std::char_traits<char>::eof(),"actual fixture geometry");}else w=make_weights();std::unique_ptr<Stage>p[2];for(int gpu=0;gpu<2;++gpu){ck(cudaSetDevice(gpu));int l2=0;ck(cudaDeviceGetAttribute(&l2,cudaDevAttrL2CacheSize,gpu));need(HalfBytes>2*size_t(l2),"half head not cold on actualGPU");p[gpu]=std::make_unique<Stage>(gpu,w);}w.clear();w.shrink_to_fit();
 for(int nt=1;nt<=8;++nt){std::unique_ptr<G>graphs[2][3];for(int gpu=0;gpu<2;++gpu){auto&z=*p[gpu];ck(cudaSetDevice(gpu));for(int v=0;v<3;++v){const int part=v-1;graphs[gpu][v]=std::make_unique<G>(z.stream,[&,part]{z.project(nt,part);z.select(nt,part,true);});graphs[gpu][v]->proof(static_cast<uint8_t*>(z.weight.p)+(part==1?HalfBytes:0),part<0?V:Half);}}
 for(int phase=0;phase<3;++phase){std::vector<float>full[2],normal[2];std::vector<uint8_t>quant[2],interleaved[2];std::vector<int32_t>fullids[2];S::HeadPick local[2][2][T];for(int gpu=0;gpu<2;++gpu){auto&z=*p[gpu];z.input(nt,phase,actual?&gamma:nullptr);z.guard(z.full);graphs[gpu][0]->run(z.stream);z.check_guard(z.full,nt*V);full[gpu]=read<float>(z.full,size_t(V)*nt,z.stream);normal[gpu]=read<float>(z.normal,H*nt,z.stream);quant[gpu]=read<uint8_t>(z.q,K::native_q8_1_bytes(H,nt),z.stream);if(nt>1)interleaved[gpu]=read<uint8_t>(z.il,K::native_q8_1_il_bytes(H,nt),z.stream);fullids[gpu].resize(nt);for(int t=0;t<nt;++t)fullids[gpu][t]=z.hostpair.p[t].id;
 for(int part=0;part<2;++part){z.guard(z.half);graphs[gpu][part+1]->run(z.stream);z.check_guard(z.half,nt*Half);auto half=read<float>(z.half,size_t(Half)*nt,z.stream);std::vector<float>expected(half.size());for(int t=0;t<nt;++t)std::copy_n(full[gpu].data()+size_t(t)*V+part*Half,Half,expected.data()+size_t(t)*Half);eq(half,expected,"sameGPU full-vs-slice Q6 logits differ");eq(normal[gpu],read<float>(z.normal,H*nt,z.stream),"half normalization differs");eq(quant[gpu],read<uint8_t>(z.q,quant[gpu].size(),z.stream),"half plainQ81 differs");if(nt>1)eq(interleaved[gpu],read<uint8_t>(z.il,interleaved[gpu].size(),z.stream),"half IL/wideQ81 differs");for(int t=0;t<nt;++t){local[gpu][part][t]=z.hostpair.p[t];int id=z.hostpair.p[t].id;need(id>=part*Half&&id<(part+1)*Half,"local ID outside partition");float value=full[gpu][size_t(t)*V+id];need(!std::memcmp(&value,&z.hostpair.p[t].score,4),"selected score bits differ");}f32_count+=size_t(nt)*(Half+H);q_count+=quant[gpu].size()+interleaved[gpu].size();}
 }
 eq(full[0],full[1],"original fullhead crossGPU logits differ");eq(normal[0],normal[1],"crossGPU normal differs");eq(quant[0],quant[1],"crossGPU plainQ81 differs");eq(interleaved[0],interleaved[1],"crossGPU IL/wide differs");eq(fullids[0],fullids[1],"crossGPU original picks differ");f32_count+=size_t(nt)*(V+H);q_count+=quant[0].size()+interleaved[0].size();for(int gpu=0;gpu<2;++gpu){int32_t merged[T];S::merge_head_picks(local[gpu][0],local[gpu][1],nt,V,merged);eq(fullids[gpu],std::vector<int32_t>(merged,merged+nt),"sameGPU merged picks differ");id_count+=nt;}int32_t cross[T];S::merge_head_picks(local[0][0],local[1][1],nt,V,cross);eq(fullids[0],std::vector<int32_t>(cross,cross+nt),"twoGPU merged picks differ");id_count+=2*nt;
 }}
 sampler_controls(*p[0],*p[1]);std::cout<<"NUMERIC PASS F32_values="<<f32_count<<" quant_bytes="<<q_count<<" IDs="<<id_count<<" BOTHGPU NT1..8/3changedcaptures/full-and-bothhalves/crossGPU/alllogits/outputguards/weightoffsetproof\n";
 if(!actual&&!(argc==2&&std::string(argv[1])=="--correctness-only")){constexpr int nt=3;for(auto&z:p)z->input(nt,1);int32_t merged[T];auto original=[&]{auto&z=*p[0];ck(cudaSetDevice(0));z.project(nt,-1);for(int gpu=0;gpu<2;++gpu){ck(cudaSetDevice(gpu));ck(cudaStreamSynchronize(p[gpu]->stream));}ck(cudaSetDevice(0));z.select(nt,-1,false);ck(cudaStreamSynchronize(z.stream));};auto parallel=[&]{for(int gpu=0;gpu<2;++gpu){auto&z=*p[gpu];ck(cudaSetDevice(gpu));z.project(nt,gpu);z.select(nt,gpu,true);}for(int gpu=0;gpu<2;++gpu){ck(cudaSetDevice(gpu));ck(cudaStreamSynchronize(p[gpu]->stream));}S::merge_head_picks(p[0]->hostpair.p,p[1]->hostpair.p,nt,V,merged);};for(int i=0;i<8;++i){original();parallel();}double sum[2]={};int faster=0;for(int pair=0;pair<16;++pair){double ms[2];for(int order=0;order<2;++order){int v=(pair+order)%2;auto start=std::chrono::steady_clock::now();for(int k=0;k<8;++k){if(v)parallel();else original();}ms[v]=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()/8;sum[v]+=ms[v];}faster+=ms[1]<ms[0];eq(std::vector<int32_t>(p[0]->hostids.p,p[0]->hostids.p+nt),std::vector<int32_t>(merged,merged+nt),"timed merged outputs differ");std::cout<<"pair="<<pair<<" original_ms="<<ms[0]<<" parallel_ms="<<ms[1]<<" ratio="<<ms[0]/ms[1]<<'\n';}std::cout<<std::setprecision(12)<<"GATE whole SERIAL HCpre/RMS/quant/originalQ6head/greedy/CPUacquisition vs2GPUhalfheads/localgreedy/scoreD2H/CPUmerge NT3 fullweight="<<WeightBytes<<" halfweights="<<HalfBytes<<" EACH>2L2; includesallSetDevice/APIs/streamdrains; sum_old_ms="<<sum[0]<<" sum_new_ms="<<sum[1]<<" ratio="<<sum[0]/sum[1]<<" faster="<<faster<<"/16; NOmodelgainclaim\n";need(sum[0]/sum[1]>1.05&&faster==16,"full twoGPUhead gate failed >1.05 and16fast required");}
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
